-- Created in the SQL editor on 2026-10-30 and recorded here the same day. One row per event that has a source 8-K with a SEC report date: the report date, the filing date, the trading-day lag (SPY calendar),
-- whether the report date was a trading day, its weekday, the acceptance time and its Eastern window (pre_open before 09:30, intraday to 16:00, after_close), and k_star (the lag aligned to the first trading day on or after a non-trading report date).
-- Derived from event_source_filings, securities and sec_8k_report_dates; no judgment is stored in it. Result of its first check: 22,385 rows, 1,093 non-trading report dates, acceptance windows pre_open 7,300 / intraday 4,070 / after_close 11,015.
CREATE TABLE event_timing AS SELECT t.*, GREATEST(0, t.td_lag - CASE WHEN t.report_is_trading_day THEN 0 ELSE 1 END) AS k_star FROM (SELECT DISTINCT ON (esf.event_id) esf.event_id, esf.ticker, r.accession_number, r.filing_date, r.report_date, (SELECT COUNT(*) FROM spy_cal c WHERE c.d > r.report_date AND c.d <= r.filing_date)::int AS td_lag, EXISTS (SELECT 1 FROM spy_cal c WHERE c.d = r.report_date) AS report_is_trading_day, EXTRACT(DOW FROM r.report_date)::int AS report_dow, r.acceptance_datetime, (r.acceptance_datetime AT TIME ZONE $$America/New_York$$)::time AS accepted_et_time, CASE WHEN (r.acceptance_datetime AT TIME ZONE $$America/New_York$$)::time < $$09:30$$::time THEN $$pre_open$$ WHEN (r.acceptance_datetime AT TIME ZONE $$America/New_York$$)::time < $$16:00$$::time THEN $$intraday$$ ELSE $$after_close$$ END AS accepted_bucket, r.items FROM event_source_filings esf JOIN securities s ON s.ticker = esf.ticker JOIN sec_8k_report_dates r ON r.security_id = s.id AND r.accession_number = esf.accession_number WHERE r.report_date IS NOT NULL ORDER BY esf.event_id, r.report_date) t;
